components.css:
.ds-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 48px; padding: 0 20px; border: 0; border-radius: 14px;
  background: #0b57d0; color: #fff; text-decoration: none;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif; font-size: 17px; font-weight: 600; letter-spacing: -0.01em;
  box-shadow: 0 10px 22px -12px rgba(11, 87, 208, 0.85);
  transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 180ms ease;
}
.ds-btn svg { display: block; }
.ds-btn:hover { transform: translateY(-1px); }
.ds-btn:active { transform: scale(0.98); }
.ds-btn:focus-visible { outline: 2px solid #0b57d0; outline-offset: 3px; }

.ds-play-n {
  min-height: 44px;
  border: 0;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: #0b57d0;
  color: #fff;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-play-n svg { display: block; }
.ds-play-n .ds-bars { display: none; align-items: flex-end; gap: 2px; height: 12px; }
.ds-play-n.is-play svg { display: none; }
.ds-play-n.is-play .ds-bars { display: inline-flex; }
.ds-play-n .ds-bars i {
  display: block; width: 3px; height: 100%; border-radius: 2px; background: currentColor;
  transform-origin: center bottom; animation: ds-bar 0.9s ease-in-out infinite;
}
.ds-play-n .ds-bars i:nth-child(2) { animation-delay: 0.15s; height: 70%; }
.ds-play-n .ds-bars i:nth-child(3) { animation-delay: 0.3s; }
.ds-play-n:active { transform: scale(0.98); }
.ds-play-n:focus-visible { outline: 2px solid #0b57d0; outline-offset: 3px; }
@keyframes ds-bar {
  0%, 100% { transform: scaleY(0.35); }
  50% { transform: scaleY(1); }
}

