.ds-practice-row { display: flex; flex-wrap: wrap; gap: 8px; }
.ds-practice {
  min-height: 44px; padding: 0 16px; border-radius: 999px;
  border: 1px solid rgba(22, 34, 51, 0.1);
  background: rgba(255, 255, 255, 0.72); color: #0b57d0;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif; font-size: 15px; font-weight: 600; cursor: pointer;
}
.ds-practice[aria-pressed="true"] { background: #0b57d0; color: #fff; border-color: transparent; }
.ds-practice:focus-visible { outline: 2px solid #0b57d0; outline-offset: 3px; }

.ds-tag {
  display: inline-flex; align-items: center; height: 24px; padding: 0 8px;
  border-radius: 999px; background: rgba(11, 87, 208, 0.1); color: #0b57d0;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif; font-size: 12px; font-weight: 600;
}

.ds-lesson {
  display: flex; flex-direction: column; padding: 22px 22px 20px; color: #1d1d1f;
  text-decoration: none; background: rgba(247, 249, 252, 0.94);
  border: 1px solid rgba(22, 34, 51, 0.1); border-radius: 28px;
  box-shadow: 0 1px 2px rgba(28, 45, 74, 0.05), 0 18px 44px -24px rgba(28, 45, 74, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.7); font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif;
  transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 180ms ease;
}
.ds-lesson:hover { transform: translateY(-3px); }
.ds-lesson:focus-visible { outline: 2px solid #0b57d0; outline-offset: 3px; }
.ds-mark {
  margin: 0 0 18px; font-weight: 300; font-size: clamp(46px, 6vw, 72px);
  letter-spacing: -0.03em; line-height: 0.9;
}
.ds-meta {
  display: flex; align-items: center; gap: 10px; margin-bottom: 8px;
  color: #3a3a3c; font-size: 13px;
}
.ds-meta time { margin-left: auto; font-variant-numeric: tabular-nums; }
.ds-lesson-tag {
  display: inline-flex; align-items: center; height: 24px; padding: 0 8px;
  border-radius: 999px; background: rgba(11, 87, 208, 0.1); color: #0b57d0;
  font-size: 12px; font-weight: 600;
}
.ds-lesson-title { display: block; font-size: 20px; font-weight: 600; letter-spacing: -0.02em; line-height: 1.3; }
.ds-preview { display: block; margin-top: 6px; color: #3a3a3c; font-size: 15px; line-height: 1.45; }
@supports ((backdrop-filter: blur(12px)) or (-webkit-backdrop-filter: blur(12px))) {.ds-lesson { background: rgba(255, 255, 255, 0.56); -webkit-backdrop-filter: blur(22px) saturate(1.7); backdrop-filter: blur(22px) saturate(1.7); }}

.ds-word {
  display: grid;
  grid-template-columns: 104px minmax(0, 1fr);
  grid-template-areas: "art copy" "plays plays";
  gap: 10px 14px;
  padding: 12px;
  background: rgba(247, 249, 252, 0.94);
  color: #1d1d1f;
  border: 1px solid rgba(22, 34, 51, 0.1);
  border-radius: 28px;
  box-shadow: 0 1px 2px rgba(28, 45, 74, 0.05), 0 18px 44px -24px rgba(28, 45, 74, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif;
  transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 180ms ease;
}
.ds-word:hover { transform: translateY(-3px); }
.ds-word.is-on { box-shadow: 0 0 0 2px #0b57d0, 0 16px 36px -18px rgba(11, 87, 208, 0.55); }
.ds-word.is-err { box-shadow: 0 0 0 2px #7a2e1f; }
.ds-word.inset { background: none; border: 0; box-shadow: none; padding: 0; border-radius: 28px; }
.ds-art {
  grid-area: art; width: 104px; height: 104px; padding: 0; border-radius: 18px;
  border: 1px solid rgba(22, 34, 51, 0.06); background: rgba(255, 255, 255, 0.42);
  display: grid; place-items: center; cursor: pointer;
}
.ds-art.has-img { background: #fff; }
.ds-glyph { font-weight: 300; font-size: 64px; line-height: 1; letter-spacing: -0.04em; color: #0b57d0; }
.ds-copy { grid-area: copy; align-self: center; min-width: 0; }
.ds-copy h3 { margin: 0; font-size: 30px; font-weight: 600; letter-spacing: -0.03em; line-height: 1.1; }
.ds-cap { color: #0b57d0; }
.ds-ipa { margin: 4px 0 0; font-family: "Lucida Grande", "Segoe UI", "Noto Sans", "Arial Unicode MS", -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif; font-size: 16px; line-height: 1.3; color: #0b57d0; }
.ds-zh { margin: 2px 0 0; font-size: 16px; color: #3a3a3c; }
.ds-oops { display: none; margin: 6px 0 0; color: #7a2e1f; font-size: 13px; font-weight: 600; }
.ds-word.is-err .ds-oops { display: block; }
.ds-plays { grid-area: plays; display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.ds-art:active { transform: scale(0.98); }
.ds-art:focus-visible, .ds-word :focus-visible { outline: 2px solid #0b57d0; outline-offset: 3px; }
@supports ((backdrop-filter: blur(12px)) or (-webkit-backdrop-filter: blur(12px))) {.ds-word:not(.inset) { background: rgba(255, 255, 255, 0.56); -webkit-backdrop-filter: blur(22px) saturate(1.7); backdrop-filter: blur(22px) saturate(1.7); }}
