.ds-subjects {
  display: grid; padding: 6px; background: rgba(247, 249, 252, 0.94);
  border: 1px solid rgba(22, 34, 51, 0.1); border-radius: 28px;
  box-shadow: 0 1px 2px rgba(28, 45, 74, 0.05), 0 18px 44px -24px rgba(28, 45, 74, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.7); font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif;
}
.ds-subject {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 16px 18px; border-radius: 22px; color: #1d1d1f; text-decoration: none;
  transition: background 180ms ease;
}
.ds-subject + .ds-subject { box-shadow: inset 0 1px 0 rgba(22, 34, 51, 0.1); }
.ds-subject:hover { background: rgba(255, 255, 255, 0.45); }
.ds-subject:focus-visible { outline: 2px solid #0b57d0; outline-offset: 3px; }
.ds-subject strong { display: block; font-size: 22px; font-weight: 600; letter-spacing: -0.03em; }
.ds-subject small { display: block; margin-top: 2px; color: #3a3a3c; font-size: 14px; }
.ds-subject em { font-style: normal; font-weight: 600; color: #0b57d0; font-variant-numeric: tabular-nums; white-space: nowrap; }
@supports ((backdrop-filter: blur(12px)) or (-webkit-backdrop-filter: blur(12px))) {.ds-subjects { background: rgba(255, 255, 255, 0.56); -webkit-backdrop-filter: blur(22px) saturate(1.7); backdrop-filter: blur(22px) saturate(1.7); }}

.ds-topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  min-height: 60px; padding: 0 16px; background: rgba(244, 247, 251, 0.96);
  border-bottom: 1px solid rgba(22, 34, 51, 0.1); font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif;
}
.ds-brand {
  color: #1d1d1f; text-decoration: none; font-size: 17px; font-weight: 600;
  letter-spacing: -0.03em; white-space: nowrap;
}
.ds-menu { display: flex; align-items: center; gap: 2px; }
.ds-menu a {
  padding: 8px; border-radius: 999px; color: #1d1d1f; text-decoration: none;
  font-size: 14px; font-weight: 500; white-space: nowrap;
}
.ds-menu a[aria-current="page"] { color: #0b57d0; font-weight: 600; }
.ds-menu a:focus-visible, .ds-brand:focus-visible { outline: 2px solid #0b57d0; outline-offset: 3px; }
@supports ((backdrop-filter: blur(12px)) or (-webkit-backdrop-filter: blur(12px))) {
  .ds-topbar {
    background: rgba(244, 247, 251, 0.72);
    -webkit-backdrop-filter: blur(20px) saturate(1.6);
    backdrop-filter: blur(20px) saturate(1.6);
  }
}

.ds-rail {
  display: flex; gap: 4px; padding: 6px; width: max-content;
  background: rgba(244, 247, 251, 0.94);
  border: 1px solid rgba(22, 34, 51, 0.1);
  border-radius: 0 0 20px 20px;
  box-shadow: 0 1px 2px rgba(28, 45, 74, 0.05), 0 18px 44px -24px rgba(28, 45, 74, 0.38);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "PingFang SC", "Hiragino Sans GB", "Helvetica Neue", "Segoe UI", Roboto, "Noto Sans", "Noto Sans SC", "Noto Sans CJK SC", Cantarell, sans-serif;
  -webkit-backdrop-filter: blur(22px) saturate(1.7);
  backdrop-filter: blur(22px) saturate(1.7);
}
.ds-rail a {
  width: 36px; height: 36px; display: grid; place-items: center; border-radius: 999px;
  color: #1d1d1f; text-decoration: none; font-size: 14px; font-weight: 600;
}
.ds-rail a.is-current { background: #0b57d0; color: #fff; }
.ds-rail a:focus-visible { outline: 2px solid #0b57d0; outline-offset: 3px; }
